import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IonicModule } from '@ionic/angular';
import { ProductService } from '../../../data/service/product/product.service';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { AccountInterceptor } from '../../../core/utility/account.interceptor';
import { ProductComponent } from './product/product.component';
import { RouterModule } from '@angular/router';
import { PriceModule } from '../../../core/pipe/price.module';
import { SellerProductComponent } from './seller-product/seller-product.component';
import { AdminProductImageCategoryComponent } from './admin-product-image-category/admin-product-image-category.component';



@NgModule({
  declarations: [ProductComponent, SellerProductComponent, AdminProductImageCategoryComponent],
  imports: [
    CommonModule,
    IonicModule,
    HttpClientModule,
    RouterModule,
    PriceModule
  ],
  providers: [
    ProductService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ],
  exports: [ProductComponent, SellerProductComponent, AdminProductImageCategoryComponent]
})
export class SharedProductModule { }
