/* eslint-disable @typescript-eslint/naming-convention */
import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { GResponse } from 'src/app/core/common/GResponse';
import { IProductCategoryModel, ProductCategoryModel } from 'src/app/data/model/product/ProductCategoryModel';

@Component({
  selector: 'app-admin-product-image-category',
  templateUrl: './admin-product-image-category.component.html',
  styleUrls: ['./admin-product-image-category.component.scss']
})
export class AdminProductImageCategoryComponent implements OnInit {

  @Input() selectedCategory = 'tuning';
  @Output() SelectEvent = new EventEmitter<IProductCategoryModel>();

  mechanicCategories: ProductCategoryModel[] = [];
  tuningCategories: ProductCategoryModel[] = [];
  designeCategories: ProductCategoryModel[] = [];

  constructor() {

  }

  ngOnInit(): void {

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    GResponse.ProductCategory.forEach(c => {

      if (c.parentId == 1) {
        this.mechanicCategories.push(c);
      } else if (c.parentId == 2) {
        this.tuningCategories.push(c);
      } else if (c.parentId == 3) {
        this.designeCategories.push(c);
      }
    });
  }

  onClick(id: string | number, title: string, url: string, parentId: string | number) {

    this.SelectEvent.emit(new ProductCategoryModel(+id, title, url, +parentId));
  }
}
