import { Component, Input, OnInit } from '@angular/core';
import { IProductModel } from '../../../../data/model/product/ProductModel';
import { Router } from '@angular/router';
import { G } from '../../../../core/common/G';

@Component({
  selector: 'app-product',
  templateUrl: './product.component.html',
  styleUrls: ['./product.component.scss']
})
export class ProductComponent implements OnInit {

  @Input() product: IProductModel;
  windowWidth = 1000;

  constructor(private router: Router) {

    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  ngOnInit(): void {
  }

  getTeacherName() {

    if (this.product.seller == undefined || this.product.seller == null) {

      return '';
    }

    // tslint:disable-next-line: max-line-length
    return this.product.seller.name != null ? this.product.seller.name : '' + ' ' + this.product.seller.family != null ? this.product.seller.family : '';
  }

  onClick() {

    this.router
      .navigate(
        ['/p', this.product.id]);
  }

  onCheckNew() {

    let date1 = new Date(this.product.createDate);
    let date2 = new Date();

    let diff = date2.getTime() - date1.getTime();

    let days = Math.floor(diff / (1000 * 60 * 60 * 24));
    diff -= days * (1000 * 60 * 60 * 24);

    let hours = Math.floor(diff / (1000 * 60 * 60));
    diff -= hours * (1000 * 60 * 60);

    let mins = Math.floor(diff / (1000 * 60));
    diff -= mins * (1000 * 60);

    let seconds = Math.floor(diff / (1000));
    diff -= seconds * (1000);

    if (days < 30) {

      return true;
    } else {

      return false;
    }
  }
}
