import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { IProductModel } from 'src/app/data/model/product/ProductModel';

@Component({
  selector: 'app-seller-product',
  templateUrl: './seller-product.component.html',
  styleUrls: ['./seller-product.component.scss']
})
export class SellerProductComponent implements OnInit {

  @Input() product: IProductModel;
  @Output() SelectEvent = new EventEmitter<string | number>();
  @Output() SelectEvent2 = new EventEmitter<IProductModel>();

  constructor() { }

  ngOnInit(): void {
  }

  getTeacherName() {

    if (this.product.seller == undefined || this.product.seller == null) {

      return '';
    }

    // tslint:disable-next-line: max-line-length
    return this.product.seller.name != null ? this.product.seller.name : '' + ' ' + this.product.seller.family != null ? this.product.seller.family : '';
  }

  onClick() {
    this.SelectEvent.emit(this.product.id);
    this.SelectEvent2.emit(this.product);
  }

  onCheckNew() {

    let date1 = new Date(this.product.createDate);
    let date2 = new Date();

    let diff = date2.getTime() - date1.getTime();

    let days = Math.floor(diff / (1000 * 60 * 60 * 24));
    diff -= days * (1000 * 60 * 60 * 24);

    let hours = Math.floor(diff / (1000 * 60 * 60));
    diff -= hours * (1000 * 60 * 60);

    let mins = Math.floor(diff / (1000 * 60));
    diff -= mins * (1000 * 60);

    let seconds = Math.floor(diff / (1000));
    diff -= seconds * (1000);

    if (days < 30) {

      return true;
    } else {

      return false;
    }
  }
}
